from pathlib import Path
import pandas as pd,numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
out=Path('outputs/point_dume_coverage_20261101');p=pd.read_csv(out/'pooled.csv');c=pd.read_csv(out/'coverage_categories.csv');f=pd.read_csv(out/'footprint_ratios.csv');sl=pd.read_csv(out/'footprint_slopes.csv');effects=pd.read_csv(out/'effects.csv')
labels={'M. pyrifera':'Kelp','S. pulcher':'Sheephead','P. interruptus':'Lobster','M. franciscanus':'Red urchin','S. purpuratus':'Purple urchin'}
order=[('M. pyrifera','Bio'),('S. pulcher','Bio'),('S. pulcher','Den'),('P. interruptus','Bio'),('P. interruptus','Den'),('M. franciscanus','Bio'),('M. franciscanus','Den'),('S. purpuratus','Bio'),('S. purpuratus','Den')]
def lab(tx,r):return labels[tx]+(' biomass' if r=='Bio' else ' density')
def get(s,tx,r,mt='Post_slope'):
 x=p[(p.scenario==s)&(p.Taxa==tx)&(p.Resp==r)&(p.metric==mt)];return None if x.empty else x.iloc[0]
def text(r):
 if r is None:return 'Unavailable'
 ans=f'{100*np.expm1(r.estimate):+.1f}%'
 if np.isfinite(r.low):ans+=f' [{100*np.expm1(r.low):+.1f}, {100*np.expm1(r.high):+.1f}]; q={r.q:.3f}'
 else:ans+='; no reliable pooled interval'
 return ans
# Compare coverage choices; all accepted histories retain their entire observed follow-up.
fig,ax=plt.subplots(figsize=(11,7.6));fig.subplots_adjust(left=.25,right=.98,bottom=.12,top=.97)
for j,(tx,r) in enumerate(order):
 for s,offset,color in [('All_three_year',-.23,'#777777'),('n5_span5_earlyany',0,'#C05B2C'),('n5_span5_early3',.23,'#286785')]:
  x=get(s,tx,r)
  if x is None:continue
  fn=lambda v:100*np.expm1(v)
  if np.isfinite(x.low):ax.plot([fn(x.low),fn(x.high)],[j+offset]*2,color=color,lw=1.4)
  ax.plot(fn(x.estimate),j+offset,'o',color=color,mfc=color if np.isfinite(x.low) else 'white',ms=5)
ax.set_yticks(range(len(order)));ax.set_yticklabels([lab(*x) for x in order]);ax.invert_yaxis();ax.axvline(0,color='.6',ls='--',lw=.8);ax.set_xlabel('Annual change in protected/reference ratio (%)');ax.spines[['top','right']].set_visible(False);ax.grid(axis='x',alpha=.15)
fig.savefig(out/'coverage_comparison.png',dpi=180,bbox_inches='tight');fig.savefig(out/'coverage_comparison.pdf',bbox_inches='tight');plt.close(fig)
fig,axs=plt.subplots(1,3,figsize=(11,3.9));fig.subplots_adjust(left=.08,right=.98,bottom=.2,top=.97,wspace=.4)
for ax,tx in zip(axs,['M. franciscanus','S. purpuratus','P. interruptus']):
 for s,color,marker in [('Seasonal_available','#777777','o'),('Seasonal_fixed_within_site','#C05B2C','s'),('All_months_common_zones','#286785','^')]:
  z=f[(f.scenario==s)&(f.Taxa==tx)].sort_values('year');ax.plot(z.year,np.exp(z.ln_ratio),marker+'-',color=color,ms=5)
 ax.set_yscale('log');ax.set_xticks([2021,2022,2023]);ax.set_ylabel(labels[tx]+' ratio');ax.set_xlabel('Survey year');ax.axhline(1,color='.6',ls='--',lw=.8);ax.spines[['top','right']].set_visible(False)
fig.savefig(out/'point_dume_footprints.png',dpi=180,bbox_inches='tight');fig.savefig(out/'point_dume_footprints.pdf',bbox_inches='tight');plt.close(fig)
# Timing inventory, one row per response history; no effect-dependent sorting.
z=c.sort_values(['category','MPA','Source','Taxa','Resp']);fig,ax=plt.subplots(figsize=(10,10));fig.subplots_adjust(left=.2,right=.97,bottom=.09,top=.98)
colors={'Early-start multiyear trajectory':'#286785','Later-start multiyear trajectory':'#C05B2C','Short-period trajectory':'#777777'}
for j,(_,r) in enumerate(z.iterrows()):
 ages=np.array([int(y) for y in r.after_years.split(';')])-int(r.after_years.split(';')[0])+r.first_age
 ax.scatter(ages,np.repeat(j,len(ages)),color=colors[r.category],s=4)
starts=[];labs=[]
for cat in z.category.unique():ii=np.flatnonzero(z.category.to_numpy()==cat);starts.append((ii[0]+ii[-1])/2);labs.append(cat.replace(' trajectory','').replace(' multiyear','\nmultiyear').replace('Short-period','Short-period'))
ax.set_yticks(starts,labs);ax.invert_yaxis();ax.set_xlabel('Years since protection');ax.set_xticks([1,3,5,10,15,20]);ax.spines[['top','right']].set_visible(False);fig.savefig(out/'survey_timing.png',dpi=180,bbox_inches='tight');fig.savefig(out/'survey_timing.pdf',bbox_inches='tight');plt.close(fig)
lines=['# Point Dume comparability and consistent recovery coverage','', 'November 1, 2026. Review only. No manuscript, source-data or canonical-pipeline changes. Researcher/ecological exclusions remain fixed.','', '## Finding','', 'Point Dume’s three late years are not equivalent to a longer record beginning near protection. More importantly, its season-filtered2023 comparison samples different depth zones from2021–2022. This is a documented footprint problem, not a reason inferred from an inconvenient slope. It weakens interpretation of the unstandardized three-year slope as recovery.','', '## Source evidence','', '- Same protected station: LECHUZA. Same late-period reference: NICHOLAS_CANYON_W. Both use VRG swath methods in2021–2023, with two transects per sampled zone. Stable station names do not mean stable survey footprints.','- The inherited May–October rule removes both stations’ December2013,2019 and2020 swath surveys. These records exist in the source; they are not missing surveys. They cannot simply be added without reviewing seasonal rules consistently.','- In2021–2022, retained protected surveys cover INNER+MID (four transects); reference surveys cover INNER+MID+OUTER (six). In2023, November surveys are filtered out, leaving protectedMID and referenceOUTER (two transects each). Protected retained depth is about10.4–10.7m versus reference12.8–13.1m.','- There is no shared depth-zone label between protected and reference sites under the2023 seasonal filter. Keeping fixed within-site seasonal zones uses protectedMID/referenceOUTER; that stabilizes each footprint but does not match habitat across sites.','- Using INNER+MID at both sites in all three years requires retaining November2023. That diagnostic holds zones fixed, but protectedMID was surveyed inSeptember and referenceMID inNovember, so it does not eliminate temporal mismatch. Do not promote it as a fully corrected primary series.','', '## What the footprint comparisons show','', 'Offset-adjusted protected/reference ratios use the same original taxon-specific additive correction in every variant. Raw site densities are exported separately. These are descriptive three-year checks, not reliable ecological recovery-rate estimates.','', '| Response / sampling choice | 2021 ratio | 2023 ratio | Log slope per year |','|---|---:|---:|---:|']
for tx in ['M. franciscanus','S. purpuratus','P. interruptus']:
 for s in ['Seasonal_available','Seasonal_fixed_within_site','All_months_common_zones']:
  r=sl[(sl.Taxa==tx)&(sl.scenario==s)].iloc[0];lines.append(f'| {labels[tx]} / {s} | {r.ratio_2021:.3f} | {r.ratio_2023:.3f} | {r.slope:+.3f} |')
lines+=['','Purple-urchin ratios change from approximately0.05→4.2 with changing seasonal footprints, versus0.03→0.08 using common INNER/MID zones with November retained. A positive local trend remains, but its magnitude and whether ratios exceed one are highly sampling-dependent. Red-urchin and lobster trends also vary among footprint choices. Do not describe the audit as disproving biological change.','', '## Proposed rule, based on the recovery question','', 'For the primary slope summary of recovery since protection, require all three:','', '1. At least five actual paired post-protection survey years. This limits dependence on a two-endpoint/three-point trajectory.','2. At least five elapsed years between first and last observation. Five annual observations can span only four years; count and duration are different requirements.','3. First post-protection observation within three years of designation, so the record includes an early part of the protected period.','', 'Retain every observed follow-up year after qualifying; no nine-year cap. Apply the same rules to every taxon, program and MPA. The numerical thresholds are transparent analyst choices, not an established universal ecological minimum, and this audit follows prior inspection of results. Calling a rule outcome-independent means its inputs are coverage/design only; it does not make the historical decision preregistered.','', 'Separately require stable documented stations and survey zones, or a defensible standardization with remaining mismatches disclosed. This audit establishes a Point Dume footprint issue; it does not certify every other history’s footprint. The coverage-only results below therefore remain conditional on that design review. Unknown footprint comparability should be flagged, not silently treated as verified.','', 'Keep longer histories starting later as later-period trajectories and shorter histories as descriptive short-period observations. They remain in the data inventory and any appropriate descriptive comparisons; this is model eligibility, not removing sites.','', 'Applied to169 full-follow-up trajectories:140 early-start multiyear;8 later-start multiyear;21 short-period. All55 qualifying before–after histories meet the proposed post-coverage requirements, so those results are unchanged.','', 'The eight later-start histories comprise four AnacapaSMR PISCO benthic histories and sheephead biomass/density at BlueCavernOnshore and LongPoint. The21 short histories include PointDumeSMCA/SMR, FarnsworthOnshore, Matlahuayl and Swamis response histories. Other programs/responses at the same MPA retain their own eligibility; PointDume satellite histories remain. See coverage_categories.csv for every decision.','', '## What changes in the slopes','', 'Entries are annual percentage changes in protected/reference ratios,95%CR2 intervals and BH q across nine response slots. All accepted histories retain their original annual values, full follow-up, individual estimates and covariances. Only coverage membership changes.','', '| Response | All169 trajectories | Duration rule only:148 | Proposed early recovery rule:140 |','|---|---|---|---|']
for tx,r in order:lines.append('| '+lab(tx,r)+' | '+' | '.join(text(get(s,tx,r)) for s in ['All_three_year','n5_span5_earlyany','n5_span5_early3'])+' |')
lines+=['','The proposed early-start cohort shows positive kelp and lobster-density trajectories and negative red-urchin density, purple-urchin density and purple-urchin biomass trajectories. Their unadjusted intervals exclude zero, but all five adjusted q values are approximately0.0595, just above0.05. This is suggestive directional evidence, not five adjusted detections. Sheephead slopes and red-urchin biomass remain uncertain; lobster biomass lacks adequate independent information for a reliable pooled interval.','', 'The duration-only148-history comparison gives adjusted support for several kelp/urchin slopes (q≈0.046), whereas the early-start140-history comparison does not. We should not pick between them by that threshold crossing. They describe different temporal coverage: multiyear post-protection trajectories versus trajectories observed near designation.','', '## Sensitivity to the coverage choices','', 'The grid was written before these subset pools: observation/span minima4/3,5/5,7/7 crossed with first observation unrestricted,within3years,within5years. For first observation within3years, all three duration minima retain exactly the same140 histories and give identical results. With no early-start gate, the retained counts are165,148 and144. First observation within5years gives148,148 and144. These alternatives remain visible rather than selecting the most significant one.','', '## Verification and limits','', 'Raw source event dates are unique within the pipeline event keys. All focal raw counts are finite and nonnegative; unrecorded focal taxa were zero-filled only within observed swath events, following the existing source convention. Multiple count rows are summed rather than dropped. Raw CSV is read with its legacyLatin1 encoding; it remains at its canonical source. Species codes are explicitly mapped. No length/biomass conversion was needed for the density audit.','', 'Reconstructed42 site-year-taxon densities match the previous source export within3.6e−15; the nine inherited seasonal log ratios reproduce within1e−10. Site identities,years,months,zones,methods,depths andeffort are in survey_coverage.csv. Original offsets are fixed across footprint variants.','', 'Coverage gates and memberships, inherited effect preservation, pooled GLS points, interval arithmetic, BH correction, unchanged55before–after histories, footprint slope calculations and487protected-file hashes are verified. See source_verification.json and verification.json. Three figures were visually inspected. This does not verify permanent transect positions or all programs’ habitat equivalence, and does not resolve pre-existing baseline trends.','', '## Figures and reproduction','', '- point_dume_footprints.png/pdf: offset-adjusted ratios. Gray circles use seasonal available zones; orange squares use fixed seasonal zones within each site; blue triangles use common INNER/MID zones with all months. Dashed line indicates equality. Lines connect three observations; no inferential bands are claimed.','- coverage_comparison.png/pdf: pooled post-protection slopes. Upper gray points show all169trajectories, middle orange the148duration-qualified trajectories, lower blue the140early-start trajectories. Bars show95%CR2 intervals; open points lack reliable pooled intervals.','- survey_timing.png/pdf: each row is a response history; dots are actual survey ages, sorted by coverage category/site/program/response rather than outcome. Blue=early-start multiyear,orange=later-start multiyear,gray=short-period.','', '```sh','python3 code/tools/audit_point_dume_coverage.py','Rscript code/tools/pool_coverage_rules.R','python3 code/tools/check_point_dume_coverage.py','python3 code/tools/report_point_dume_coverage.py','```','', 'No paper update or selection-policy promotion was performed.']
(out/'README.md').write_text('\n'.join(lines)+'\n');print('Report and figures saved')
